const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};

async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function patchFns(html,name,expected,patcher){const p=parse(html),nodes=p.decl.filter(n=>n.id.name===name);assert(nodes.length===expected,`${name}: expected ${expected}, got ${nodes.length}`);let code=p.code;for(const n of nodes.slice().sort((a,b)=>b.start-a.start)){const src=code.slice(n.start,n.end),next=patcher(src,n);assert(typeof next==='string'&&next!==src,`${name}: patch produced no change`);code=code.slice(0,n.start)+next+code.slice(n.end)}return html.slice(0,p.start)+code+html.slice(p.sc)}
function replaceOnce(src,oldText,newText,label){const n=src.split(oldText).length-1;assert(n===1,`${label}: expected 1 anchor, got ${n}`);return src.replace(oldText,newText)}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
function snap(P){return{crystals:{...(P.crystals||{})},equipment:(P.equipment||[]).map(e=>({...e})),artifacts:[...(P.artifacts||[])],battlefield:[...(P.battlefield||[])]}}

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};
 let html=index.text;console.log('Current Mobile blob '+index.sha);
 const marker='window.SIZA={';assert(html.includes(marker),'SIZA export marker missing');
 const probe=`window.__EQ_TEST__={createMatch,setMatch:m=>state.match=m,getMatch:()=>state.match,normalizeMatchV600,resolveTopStack,effectivePower,beginEquip,chooseEquipCrystalV070,equipTo,equipPanelHtml,enemyChoosePlay,matchCardMini,TEST_CARD_DB_V1};\n`;
 const oldDom=makeDom(inlineCore(html,files).replace(marker,probe+marker),'old');oldDom.window.setTimeout=()=>0;

 html=patchFns(html,'normalizeMatchV600',1,src=>replaceOnce(src,"if(c.id==='tideblade')equipment.push({id,target:null});else artifacts.push(id)","if(isEquipmentCardV1(c))equipment.push({id,target:null});else artifacts.push(id)",'normalizeMatchV600 equipment classification'));
 const helpers=`function isEquipmentCardV1(c){return !!(c?.type==='Artifact'&&((c.equipCost||0)>0||SizaCardEffects.forEvent(c,'equipped').length))}\nfunction equipmentEquipCostV1(c){return Math.max(0,Number(c?.equipCost)||0)}\nfunction equipmentPowerBonusV1(P,i){return equipmentFor(P,i).reduce((sum,e)=>{const c=cardById(e.id);return sum+SizaCardEffects.forEvent(c,'equipped').filter(x=>x.type==='modify-power').reduce((n,x)=>n+(x.amount||0),0)},0)}\nfunction effectivePower(P,i){const c=cardById(P.battlefield[i]);return(c?.power||0)+counterV070(P,i)+equipmentPowerBonusV1(P,i)}`;
 html=patchFns(html,'effectivePower',1,()=>helpers);
 html=patchFns(html,'matchCardMini',2,(src,n)=>{const arg=n.params[2]?.name;assert(arg,'matchCardMini third parameter missing');return replaceOnce(src,'eq.length*2',`equipmentPowerBonusV1(P,${arg})`,`matchCardMini ${arg} equipment badge`)});
 html=patchFns(html,'resolveTopStack',1,src=>replaceOnce(src,"if(c.id==='tideblade')P.equipment.push({id:c.id,target:null});else P.artifacts.push(c.id)","if(isEquipmentCardV1(c))P.equipment.push({id:c.id,target:null});else P.artifacts.push(c.id)",'resolveTopStack equipment classification'));
 html=patchFns(html,'beginEquip',1,()=>"function beginEquip(i){const M=state.match,P=M?.player,eq=P?.equipment?.[i],c=cardById(eq?.id),cost=equipmentEquipCostV1(c);if(!M||M.active!=='player'||M.phase!=='Main'||!eq||!P.battlefield.length)return;if(cost!==1)return toast('Este runtime sólo admite Equipar {1}.','bad');if(!Object.values(P.crystals||{}).some(Boolean))return toast('Equipar {1} requiere un cristal.','bad');M.pendingEquip={eqIndex:i,color:null};render()}");
 html=patchFns(html,'equipPanelHtml',1,()=>"function equipPanelHtml(){const M=state.match,Q=M?.pendingEquip;if(!Q)return'';const P=M.player,eq=P.equipment[Q.eqIndex],c=cardById(eq.id),cost=equipmentEquipCostV1(c),colors=['U','R','G','W','B'].filter(k=>(P.crystals?.[k]||0)>0);return `<div class=\"equipPanelV600\"><h3>Equipar ${c.name} · {${cost}}</h3><p>Elige el cristal; la Arena no decide el color ocultamente.</p><div class=\"paymentRowV070\">${colors.map(k=>`<button class=\"paymentChoiceV070 ${Q.color===k?'selected':''}\" onclick=\"SIZA.chooseEquipCrystalV070('${k}')\">${COLORS[k]}</button>`).join('')}</div><div class=\"equipChoicesV600\">${P.battlefield.map((id,i)=>{const x=cardById(id);return `<button class=\"equipChoiceV600\" ${Q.color?'':'disabled'} onclick=\"SIZA.equipTo(${i})\">${cardThumbHtmlV1(x,{stats:{power:effectivePower(P,i),toughness:toughV070(P,i)}})}<span>${x.name}</span></button>`}).join('')}</div></div>`}");
 html=patchFns(html,'equipTo',1,()=>"function equipTo(i){const M=state.match,Q=M?.pendingEquip;if(!Q?.color)return;const P=M.player,eq=P.equipment[Q.eqIndex],c=cardById(eq.id),cost=equipmentEquipCostV1(c);if(cost!==1)return;spendV070(P,{[Q.color]:cost});eq.target=i;addLog('Equipar',`${c.name} se equipa a ${cardById(P.battlefield[i]).name}; paga ${COLORS[Q.color]}.`);M.pendingEquip=null;save();render()}");
 html=patchFns(html,'enemyChoosePlay',1,src=>replaceOnce(src,"const loose=E.equipment.findIndex(e=>e.target==null),color=", "const loose=E.equipment.findIndex(e=>e.target==null&&equipmentEquipCostV1(cardById(e.id))===1),color=",'enemyChoosePlay equip eligibility'));

 const parsed=parse(html);for(const name of ['normalizeMatchV600','resolveTopStack','effectivePower','beginEquip','equipPanelHtml','equipTo','enemyChoosePlay'])assert(parsed.decl.some(n=>n.id.name===name),name+' missing after transform');
 const eqFns=parsed.decl.filter(n=>['normalizeMatchV600','resolveTopStack','effectivePower'].includes(n.id.name)).map(n=>parsed.code.slice(n.start,n.end)).join('\n');assert(!eqFns.includes("id==='tideblade'")&&!eqFns.includes("e.id==='tideblade'"),'Tideblade ID hardcoding remains in migrated equipment paths');

 const newProbe=`window.__EQ_TEST__={createMatch,setMatch:m=>state.match=m,getMatch:()=>state.match,normalizeMatchV600,resolveTopStack,effectivePower,beginEquip,chooseEquipCrystalV070,equipTo,equipPanelHtml,enemyChoosePlay,matchCardMini,TEST_CARD_DB_V1,isEquipmentCardV1,equipmentEquipCostV1,equipmentPowerBonusV1};\n`;
 const newDom=makeDom(inlineCore(html,files).replace(marker,newProbe+marker),'new');newDom.window.setTimeout=()=>0;
 const oldH=oldDom.window.__EQ_TEST__,newH=newDom.window.__EQ_TEST__;

 function setupPower(dom,H){const M=H.createMatch(false,'prepare');H.setMatch(M);M.player.battlefield=['servitor'];M.player.powerCounters=[0];M.player.summonedOn=[0];M.player.equipment=[{id:'tideblade',target:0}];return{M,power:H.effectivePower(M.player,0)}}
 const po=setupPower(oldDom,oldH),pn=setupPower(newDom,newH);assert(po.power===4&&pn.power===4,'Tideblade official +2 old/new mismatch');console.log('PASS equivalence Tideblade +2/+0');

 function setupEquip(H){const M=H.createMatch(false,'prepare');H.setMatch(M);M.active='player';M.phase='Main';M.player.battlefield=['servitor'];M.player.powerCounters=[0];M.player.summonedOn=[0];M.player.equipment=[{id:'tideblade',target:null}];M.player.crystals={U:1,R:1};H.beginEquip(0);H.chooseEquipCrystalV070('U');H.equipTo(0);return snap(M.player)}
 assert(JSON.stringify(setupEquip(oldH))===JSON.stringify(setupEquip(newH)),'Tideblade equip payment/target old/new mismatch');console.log('PASS equivalence Equipar {1} payment and target');

 function setupResolve(H){const M=H.createMatch(false,'prepare');H.setMatch(M);M.player.equipment=[];M.player.artifacts=[];M.stack=[{id:'eq-stack',cardId:'tideblade',owner:'player'}];H.resolveTopStack();return snap(M.player)}
 assert(JSON.stringify(setupResolve(oldH))===JSON.stringify(setupResolve(newH)),'Tideblade resolve zone old/new mismatch');console.log('PASS equivalence Tideblade enters Equipment zone');

 function setupAi(H){const M=H.createMatch(false,'prepare');H.setMatch(M);M.active='enemy';M.enemy.equipment=[{id:'tideblade',target:null}];M.enemy.battlefield=['servitor'];M.enemy.powerCounters=[0];M.enemy.summonedOn=[0];M.enemy.crystals={U:1,R:1};H.enemyChoosePlay();return snap(M.enemy)}
 assert(JSON.stringify(setupAi(oldH))===JSON.stringify(setupAi(newH)),'Tideblade AI equip old/new mismatch');console.log('PASS equivalence AI Equipar {1}');

 const generated={id:'generated_blade',name:'Generated Blade',type:'Artifact',cost:1,difficulty:1,pips:{},equipCost:1,text:'Equipped creature gets +3/+0.',art:'multi',glyph:'B',effects:[{event:'equipped',type:'modify-power',amount:3}]};newH.TEST_CARD_DB_V1.push(generated);
 let M=newH.createMatch(false,'prepare');newH.setMatch(M);M.player.equipment=[];M.player.artifacts=[];M.stack=[{id:'generated-stack',cardId:'generated_blade',owner:'player'}];newH.resolveTopStack();assert(M.player.equipment[0]?.id==='generated_blade'&&M.player.artifacts.length===0,'Generated equipment did not enter Equipment zone');M.player.battlefield=['servitor'];M.player.powerCounters=[0];M.player.summonedOn=[0];M.player.crystals={U:1,R:1};newH.beginEquip(0);newH.chooseEquipCrystalV070('U');newH.equipTo(0);assert(newH.effectivePower(M.player,0)===5,'Generated equipment +3 did not affect power');assert(newH.matchCardMini('servitor','player',0).includes('+3/+0'),'Generated equipment badge did not show +3/+0');console.log('PASS generated Equipment zone + Equipar {1} +3 power');

 M=newH.createMatch(false,'prepare');newH.setMatch(M);M.player.battlefield=['generated_blade'];M.player.powerCounters=[0];M.player.summonedOn=[0];M.player.equipment=[];M.player.artifacts=[];newH.normalizeMatchV600();assert(M.player.battlefield.length===0&&M.player.equipment[0]?.id==='generated_blade','Generated saved-state equipment normalization failed');console.log('PASS generated Equipment saved-state normalization');

 const core=newDom.window.SIZA.runArenaCriticalV071();for(const r of core.results)console.log((r.pass?'PASS':'FAIL')+' '+r.name+(r.error?' :: '+r.error:''));assert(core.passed===core.total,'Arena '+core.passed+'/'+core.total);console.log('PASS Arena '+core.passed+'/'+core.total);
 oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Resolve Equipment behavior from card data',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
